import amqplib from 'amqplib';
import { examples_order_service_process_shipment } from './handlers/examples-order-service-process-shipment';

const QUEUE_EXAMPLES_ORDER_SERVICE_PROCESS_SHIPMENT = 'order-service.process-shipment';

async function handleExamplesOrderServiceProcessShipment(
  channel: amqplib.Channel,
  msg: amqplib.ConsumeMessage,
): Promise<void> {
  try {
    const payload = JSON.parse(msg.content.toString()) as Record<string, unknown>;
    await Promise.race([
      examples_order_service_process_shipment(payload),
      new Promise<never>((_, reject) => {
        setTimeout(() => reject(new Error('serverless_queue_timeout')), 300000);
      }),
    ]);
    channel.ack(msg);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    if (message === 'serverless_queue_timeout') {
      console.error(`serverless_queue_timeout handler=examples_order_service_process_shipment timeout_ms=300000`);
    } else {
      console.error(`serverless_queue_dispatch_failed handler=examples_order_service_process_shipment error=${message}`);
    }
    channel.nack(msg, false, false);
  }
}


async function main(): Promise<void> {
  const amqpUrl = process.env.QUEUE_AMQP_URL;
  if (!amqpUrl) {
    throw new Error('QUEUE_AMQP_URL environment variable is required');
  }
  const connection = await amqplib.connect(amqpUrl);
  const channel = await connection.createChannel();

  await channel.assertQueue(QUEUE_EXAMPLES_ORDER_SERVICE_PROCESS_SHIPMENT, { durable: true });
  await channel.consume(QUEUE_EXAMPLES_ORDER_SERVICE_PROCESS_SHIPMENT, (msg) => {
    if (msg) {
      void handleExamplesOrderServiceProcessShipment(channel, msg);
    }
  });
  console.log(`serverless_queue_worker_bound block=queue-workers queue=${QUEUE_EXAMPLES_ORDER_SERVICE_PROCESS_SHIPMENT}`);

  const shutdown = async (signal: string): Promise<void> => {
    console.log(`shutdown_signal_received signal=${signal}`);
    await channel.close();
    await connection.close();
    console.log('serverless_queue_worker_stopped block=queue-workers');
    process.exit(0);
  };
  process.on('SIGTERM', () => {
    void shutdown('SIGTERM');
  });
  process.on('SIGINT', () => {
    void shutdown('SIGINT');
  });
}

main().catch((err) => {
  console.error('Container serverless queue worker failed to start', err);
  process.exit(1);
});
